INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('apb---all-points-bulletin-usa-europe', 'Atari Lynx', 'A.P.B. - All Points Bulletin (USA, Europe)', '1989', 'Action', 'Atari Games', '1-2', 'Top-down police action', 'Top-down driving action game with arcade physics.', 'Apprehend dangerous criminals while meeting daily ticket quotas.', 'A faithful port of the Atari arcade hit featuring smooth sprite scaling.', 'A.P.B. on Atari Lynx brings high-speed police chases to the palm of your hand. Navigate city streets, avoid demerits, and bust lawbreakers in this technically impressive handheld port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-vs-predator-usa-proto', 'Atari Lynx', 'Alien vs Predator (USA) (Proto)', '1993', 'Action', 'Rebellion Developments', '1', 'Run-and-gun shooter', 'First-person survival horror (unreleased development build).', 'Navigate dark corridors to hunt humans or survive alien encounters.', 'A rare look at a planned 8-bit handheld version of the sci-fi franchise.', 'Alien vs Predator (Proto) for Atari Lynx offers a fascinating glimpse into what could have been. Explore early 3D-style environments in this atmospheric unreleased prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('awesome-golf-usa-europe', 'Atari Lynx', 'Awesome Golf (USA, Europe)', '1991', 'Sports', 'Atari', '1', 'Golf arcade sports', 'Third-person perspective golf simulation.', 'Complete 18 holes across various international courses in the fewest strokes.', 'A detailed golf sim that utilizes the Lynx’s scaling for realistic depth.', 'Awesome Golf on Atari Lynx delivers a premier portable sporting experience. Master the wind and terrain in this visually impressive and deep golf simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baseball-heroes-usa-europe', 'Atari Lynx', 'Baseball Heroes (USA, Europe)', '1992', 'Sports', 'Atari', '1', 'Baseball arcade sports', 'Traditional overhead baseball simulation.', 'Lead your team through a full season to win the championship.', 'A sports title featuring clear sprites and intuitive arcade-style controls.', 'Baseball Heroes for Atari Lynx provides classic diamond action on the go. Pitch, hit, and slide your way to victory in this competitive and fun handheld sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('basketbrawl-usa-europe', 'Atari Lynx', 'Basketbrawl (USA, Europe)', '1990', 'Sports', 'Atari', '1-2', 'Street basketball action', 'Side-scrolling combat-sports hybrid.', 'Win basketball games by scoring points and physically attacking rivals.', 'A gritty street-sports game where violence is part of the strategy.', 'Basketbrawl on Atari Lynx combines hoops and hand-to-hand combat. Navigate a dangerous court in this unique and aggressive take on portable basketball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-returns-usa-europe', 'Atari Lynx', 'Batman Returns (USA, Europe)', '1992', 'Action', 'Konami', '1', 'Side-scrolling action platformer', 'Side-scrolling action-platformer based on the 1992 film.', 'Fight through Gotham City as Batman to defeat the Penguin and Catwoman.', 'A dark, moody action game featuring large sprites and detailed backgrounds.', 'Batman Returns for Atari Lynx is a cinematic handheld powerhouse. Utilize gadgets and combat skills in this visually stunning 8-bit adaptation of the blockbuster movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-wheels-usa-europe', 'Atari Lynx', 'Battle Wheels (USA, Europe)', '1990', 'Action', 'Atari', '1-2', 'Top-down vehicular combat', 'First-person 3D vehicular combat in a post-apocalyptic arena.', 'Customize your car and destroy all opponents to become the champion.', 'A technically advanced 3D shooter featuring 360-degree movement.', 'Battle Wheels on Atari Lynx pushes the hardware to its limits. Experience intense first-person car combat in this innovative and high-octane 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlezone-2000-usa-europe', 'Atari Lynx', 'Battlezone 2000 (USA, Europe)', '1991', 'Shooter', 'Atari', '1', 'First-person tank shooter', 'First-person tank combat reimagined for the future.', 'Navigate wireframe and solid 3D arenas to destroy enemy tanks.', 'A modern update of the arcade classic with new modes and power-ups.', 'Battlezone 2000 for Atari Lynx brings futuristic armored warfare to the handheld screen. Master the radar and tactical movement in this deep and challenging shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bill-&-teds-excellent-adventure-usa-europe', 'Atari Lynx', 'Bill & Ted''s Excellent Adventure (USA, Europe)', '1991', 'Adventure', 'Atari', '1', 'Comedy adventure', 'Isometric action-adventure based on the movie characters.', 'Travel through time to find historical figures and pass your history report.', 'A humorous and colorful adventure featuring diverse time periods.', 'Bill & Ted''s Excellent Adventure on Atari Lynx is a totally radical quest. Solve puzzles and meet famous icons in this faithful and fun 8-bit portable adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('block-out-usa-europe', 'Atari Lynx', 'Block Out (USA, Europe)', '1990', 'Puzzle', 'California Dreams', '1', '3D falling block puzzle', 'Pseudo-3D falling block puzzle game.', 'Rotate and place 3D blocks to complete horizontal layers in a pit.', 'A unique 3D take on the Tetris formula that tests your spatial awareness.', 'Block Out for Atari Lynx offers a brain-bending puzzle challenge. Master the third dimension in this addictive and technically impressive handheld conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-lightning-usa-europe', 'Atari Lynx', 'Blue Lightning (USA, Europe)', '1989', 'Shooter', 'Epyx', '1', 'Afterburner-style flight shooter', 'Third-person pseudo-3D flight combat and exploration.', 'Pilot a high-tech fighter jet to destroy enemy forces across various biomes.', 'A flagship Lynx title showcasing incredible sprite scaling and speed.', 'Blue Lightning on Atari Lynx is a breathtaking showcase of the system''s power. Experience high-speed aerial dogfights and bombing runs in this arcade-quality flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-lightning-usa-demo', 'Atari Lynx', 'Blue Lightning (USA) (Demo)', '1989', 'Shooter', 'Epyx', '1', 'Afterburner-style flight shooter', 'Third-person pseudo-3D flight combat (promotional version).', 'Test the flight mechanics and scaling of the system''s premier jet sim.', 'A specialized demo version showing off the technical prowess of the Lynx.', 'Blue Lightning (Demo) for Atari Lynx allows players to experience the speed and scaling technology that made the system a rival to home consoles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-trouble-usa-europe', 'Atari Lynx', 'Bubble Trouble (USA, Europe)', '1992', 'Puzzle', 'Loriciel', '1', 'Arcade puzzle action', 'Side-scrolling underwater action and exploration.', 'Navigate a submarine through hazardous caves to clear all bubbles.', 'A quirky and colorful action game with a focus on physics and timing.', 'Bubble Trouble on Atari Lynx offers a unique aquatic challenge. Master the movement of your sub in this vibrant and addictive handheld arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-games-usa-europe', 'Atari Lynx', 'California Games (USA, Europe)', '1989', 'Sports', 'Epyx', '1-2', 'Multi-sport arcade collection', 'Multi-event sports simulation featuring iconic California activities.', 'Compete in BMX, surfing, skating, and more to earn the highest score.', 'The definitive handheld version of the classic Epyx sports title.', 'California Games for Atari Lynx is a masterpiece of portable gaming. Experience five distinct events featuring smooth animation and the system''s best music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('centipede-usa-proto', 'Atari Lynx', 'Centipede (USA) (Proto)', '1993', 'Shooter', 'Atari', '1', 'Classic arcade shooter', 'Fixed-screen shooter with multi-directional movement (unreleased build).', 'Blast waves of insects and spiders in this unreleased handheld port.', 'A rare prototype of the arcade legend specifically designed for the Lynx.', 'Centipede (Proto) on Atari Lynx brings the frantic energy of the arcade home. Experience this unfinished but playable version of the classic bug-blasting hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('checkered-flag-usa-europe', 'Atari Lynx', 'Checkered Flag (USA, Europe)', '1991', 'Racing', 'Atari', '1', 'Arcade racing', 'Pseudo-3D racing simulation with lap-based progression.', 'Outrace your rivals on various tracks to win the world championship.', 'A fast-paced racer that uses the Lynx''s scaling for an arcade feel.', 'Checkered Flag on Atari Lynx delivers high-speed portable racing. Master the curves and pit stops in this technically impressive 8-bit Formula 1 simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chips-challenge-usa-europe', 'Atari Lynx', 'Chip''s Challenge (USA, Europe)', '1989', 'Puzzle', 'Epyx', '1', 'Tile-based puzzle game', 'Top-down grid-based puzzle-adventure game.', 'Collect all the chips in each level to unlock the exit and progress.', 'A legendary and addictive puzzle game with 144 challenging levels.', 'Chip''s Challenge for Atari Lynx is an essential brain-teaser. Navigate traps, monsters, and complex obstacles in this definitive handheld puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crystal-mines-ii-usa-europe', 'Atari Lynx', 'Crystal Mines II (USA, Europe)', '1992', 'Action', 'Epyx', '1', 'Top-down mining shooter', 'Top-down puzzle and action game involving mining.', 'Use explosives to clear paths and find the hidden exit in each level.', 'A massive puzzle sequel featuring over 180 levels of strategic fun.', 'Crystal Mines II on Atari Lynx offers a deep and rewarding challenge. Manage your inventory and plan your blasts in this expansive 8-bit puzzle-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daemonsgate-usa-proto', 'Atari Lynx', 'Daemonsgate (USA) (Proto)', '1992', 'RPG', 'MicroProse', '1', 'Dark fantasy role-playing game', 'Isometric role-playing game (unreleased development build).', 'Explore a vast dark fantasy world and interact with hundreds of NPCs.', 'An incredibly ambitious unreleased RPG prototype for the handheld.', 'Daemonsgate (Proto) for Atari Lynx showcases what could have been a landmark handheld RPG. Experience the early world-building and mechanics of this lost 8-bit epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike---return-to-the-gulf-usa-europe', 'Atari Lynx', 'Desert Strike - Return to the Gulf (USA, Europe)', '1992', 'Action', 'Electronic Arts', '1', 'Isometric military action', 'Isometric helicopter combat and rescue simulation.', 'Infiltrate enemy territory to destroy targets and rescue POWs.', 'A technically stunning port of the multi-platform hit with fluid movement.', 'Desert Strike on Atari Lynx brings the Gulf War action to the portable screen. Master the physics of the Apache helicopter in this deep and tactical 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dinolympics-usa-europe', 'Atari Lynx', 'Dinolympics (USA, Europe)', '1992', 'Sports', 'Atari', '1-2', 'Prehistoric sports mini-games', 'Side-scrolling platformer and puzzle-adventure.', 'Guide a group of prehistoric animals through various athletic trials.', 'A humorous "caveman" themed game with creative level design.', 'Dinolympics on Atari Lynx (also known as Dino Jobs) offers a unique mix of action and puzzles. Utilize different animal abilities to overcome challenges in this quirky quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dirty-larry---renegade-cop-usa-europe', 'Atari Lynx', 'Dirty Larry - Renegade Cop (USA, Europe)', '1992', 'Action', 'Atari', '1', 'Cinematic police action', 'Side-scrolling beat ''em up and driving hybrid.', 'Clean up the streets of Steel Reef as a renegade cop using force.', 'A gritty and violent action game with large, detailed character sprites.', 'Dirty Larry: Renegade Cop for Atari Lynx delivers hard-hitting portable action. Fight through urban stages and engage in high-speed chases in this tough 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-usa-europe', 'Atari Lynx', 'Double Dragon (USA, Europe)', '1991', 'Beat ''em up', 'Imagineering', '1-2', 'Side-scrolling brawler', 'Side-scrolling beat ''em up with cooperative play support.', 'Rescue Marian from the Black Warriors gang using martial arts.', 'A faithful handheld port of the arcade legend featuring Comlynx support.', 'Double Dragon on Atari Lynx brings the Lee brothers to life with impressive graphics. Battle through city streets in this definitive 8-bit portable brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dracula-the-undead-usa-europe', 'Atari Lynx', 'Dracula the Undead (USA, Europe)', '1992', 'Adventure', 'Atari', '1', 'Horror graphic adventure', 'First-person point-and-click horror adventure.', 'Survive the journey to London while hunting the legendary Count Dracula.', 'A dark and atmospheric adventure based on the Bram Stoker novel.', 'Dracula the Undead on Atari Lynx features haunting visuals and deep exploration. Solve the mystery and survive the night in this unique and mature handheld horror title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('electrocop-usa-europe', 'Atari Lynx', 'Electrocop (USA, Europe)', '1989', 'Action', 'Epyx', '1', 'Isometric sci-fi action', 'Third-person 3D-style action and hacking simulator.', 'Infiltrate a high-tech fortress to rescue a kidnapped president''s daughter.', 'A visually groundbreaking game featuring 3D corridors and platforming.', 'Electrocop on Atari Lynx is a technical marvel. Navigate the fortress, hack computer terminals, and blast robots in this innovative 8-bit sci-fi adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('european-soccer-challenge-usa-europe', 'Atari Lynx', 'European Soccer Challenge (USA, Europe)', '1991', 'Sports', 'U.S. Gold', '1-2', 'Soccer arcade sports', 'Top-down soccer simulation with international teams.', 'Lead your chosen nation to the top of the European soccer rankings.', 'A fast-paced and smooth sports title with intuitive controls.', 'European Soccer Challenge for Atari Lynx provides addictive portable football. Master the passing and shooting mechanics in this competitive 8-bit sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eye-of-the-beholder-usa-proto', 'Atari Lynx', 'Eye of the Beholder (USA) (Proto)', '1992', 'RPG', 'Westwood Associates', '1', 'First-person dungeon crawler', 'First-person dungeon-crawling RPG (unreleased prototype).', 'Explore the sewers of Waterdeep to defeat the beholder Xanathar.', 'A rare and unfinished handheld port of the D&D masterpiece.', 'Eye of the Beholder (Proto) for Atari Lynx shows the system''s potential for deep RPGs. Experience the grid-based movement and early combat of this lost D&D classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fat-bobby-usa-europe', 'Atari Lynx', 'Fat Bobby (USA, Europe)', '1993', 'Platformer', 'Atari', '1', 'Colorful cartoon platformer', 'Side-scrolling platformer with musical and racing elements.', 'Guide Bobby through wacky levels to reach the big music competition.', 'A colorful and fast-paced adventure featuring unique character designs.', 'Fat Bobby on Atari Lynx is a vibrant and fun 8-bit platformer. Navigate obstacles and collect items in this charming and underrated handheld action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fidelity-ultimate-chess-challenge-the-usa-europe', 'Atari Lynx', 'Fidelity Ultimate Chess Challenge, The (USA, Europe)', '1991', 'Board game', 'Digital Illusions', '1', 'Chess simulation', 'Digital chess simulation with various difficulty levels.', 'Defeat the computer or a friend in a game of professional chess.', 'A sophisticated chess program featuring a clean interface and deep AI.', 'The Fidelity Ultimate Chess Challenge on Atari Lynx brings grandmaster-level play to your pocket. Test your strategy in this definitive portable chess simulation.');
