INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gordo-106---the-mutated-lab-monkey-usa-europe', 'Atari Lynx', 'Gordo 106 - The Mutated Lab Monkey (USA, Europe)', '1991', 'Action', 'Atari', '1', 'Run-and-gun platform action', 'Side-scrolling platformer with puzzle elements.', 'Escape the laboratory and free other animals from cruel experiments.', 'A quirky action game where you play as a monkey throwing apples.', 'Gordo 106 for Atari Lynx offers challenging platforming with a social message. Navigate hazardous environments and use your primate agility to survive the mutated lab.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hard-drivin-usa-europe', 'Atari Lynx', 'Hard Drivin'' (USA, Europe)', '1991', 'Racing', 'Atari Games', '1', '3D arcade driving', 'First-person 3D driving simulation with stunt tracks.', 'Complete the course within the time limit while mastering 3D physics.', 'A technically ambitious port of the groundbreaking 3D arcade racer.', 'Hard Drivin'' on Atari Lynx pushes the hardware to its limits. Experience the loop-de-loop and realistic car handling in this impressive 8-bit polygonal simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hockey-usa-europe', 'Atari Lynx', 'Hockey (USA, Europe)', '1991', 'Sports', 'Atari', '1-2', 'Ice hockey arcade sports', 'Top-down ice hockey simulation with fast-paced action.', 'Outscore your opponent in a competitive game of professional hockey.', 'A smooth and responsive sports title featuring ComLynx multiplayer.', 'Hockey for Atari Lynx brings the intensity of the rink to your pocket. Master the power-plays and body checks in this definitive portable sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hydra-usa-europe', 'Atari Lynx', 'Hydra (USA, Europe)', '1992', 'Shooter', 'Atari', '1-2', 'Top-down sci-fi shooter', 'Third-person pseudo-3D vehicular combat and delivery.', 'Deliver top-secret bio-containers while destroying enemy craft.', 'A high-speed action game featuring impressive sprite scaling and water effects.', 'Hydra on Atari Lynx is an adrenaline-fueled dash through enemy territory. Pilot your combat hovercraft through treacherous waters in this arcade-quality 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ishido---the-way-of-stones-usa-europe', 'Atari Lynx', 'Ishido - The Way of Stones (USA, Europe)', '1991', 'Puzzle', 'Accolade', '1', 'Abstract strategy puzzle', 'Tile-matching puzzle game with a meditative theme.', 'Place stones on the board matching their symbols or colors to clear it.', 'A sophisticated and strategic board game with a calm atmosphere.', 'Ishido: The Way of Stones for Atari Lynx is a perfect brain-teaser. Master the ancient patterns and symbols in this highly addictive and polished portable puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-tennis-usa-europe', 'Atari Lynx', 'Jimmy Connors'' Tennis (USA, Europe)', '1991', 'Sports', 'Blue Sky Software', '1', 'Tennis arcade sports', 'Third-person perspective tennis simulation.', 'Win the Grand Slam by defeating the world''s best tennis pros.', 'A realistic sports game featuring the likeness of the tennis legend.', 'Jimmy Connors'' Tennis on Atari Lynx delivers precise controls and fluid animation. Compete on multiple surfaces in this deep and challenging handheld sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joust-usa-europe', 'Atari Lynx', 'Joust (USA, Europe)', '1990', 'Platformer', 'Atari', '1-2', 'Classic arcade platformer', 'Single-screen combat game featuring flying mounts.', 'Defeat enemy knights by colliding with them from a higher position.', 'A pixel-perfect port of the arcade classic with smooth flight physics.', 'Joust for Atari Lynx brings the ostrich-riding action to life. Master the flap mechanics and battle waves of buzzards in this addictive high-score chaser.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-usa-europe', 'Atari Lynx', 'Klax (USA, Europe)', '1990', 'Puzzle', 'Tengen', '1', 'Falling-block puzzle', 'Pseudo-3D puzzle game focusing on falling tile management.', 'Catch and arrange colored tiles into rows to clear the board.', 'A flawless port of the arcade hit that perfectly suits the Lynx screen.', 'Klax on Atari Lynx is a puzzle masterpiece. With its vibrant colors and "catch and stack" gameplay, it remains one of the most addictive titles in the library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krazy-ace---miniature-golf-usa-europe', 'Atari Lynx', 'Krazy Ace - Miniature Golf (USA, Europe)', '1991', 'Sports', 'Telegames', '1', 'Miniature golf arcade', 'Isometric miniature golf simulation.', 'Complete various wacky mini-golf courses in the fewest strokes possible.', 'A fun and colorful sports game with creative obstacles and themes.', 'Krazy Ace: Miniature Golf for Atari Lynx offers portable putting fun. Navigate through moving hazards and creative traps in this charming and competitive 8-bit game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kung-food-usa-europe', 'Atari Lynx', 'Kung Food (USA, Europe)', '1992', 'Action', 'Atari', '1', 'Top-down comedic action', 'Side-scrolling beat ''em up with a unique food theme.', 'Fight through a kitchen infested with mutated food items to save the world.', 'A bizarre brawler where you fight giant vegetables and snacks.', 'Kung Food on Atari Lynx is a quirky and fun action title. Use your martial arts skills to pummel sentient junk food in this visually distinct 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-usa-europe', 'Atari Lynx', 'Lemmings (USA, Europe)', '1992', 'Puzzle', 'DMA Design', '1', 'Puzzle strategy game', 'Side-scrolling puzzle-strategy game.', 'Guide a group of mindless lemmings to the exit using specific skills.', 'An incredible port of the computer classic with intuitive controls.', 'Lemmings for Atari Lynx features over 100 levels of brain-teasing action. Manage your lemmings'' abilities to survive hazardous traps in this handheld essential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lexis-usa-europe', 'Atari Lynx', 'Lexis (USA, Europe)', '1991', 'Puzzle', 'Atari', '1', 'Word and logic puzzle', 'Word-building puzzle game with falling blocks.', 'Form words from falling letters to clear lines and score points.', 'A unique "Scrabble-meets-Tetris" hybrid designed for the Lynx.', 'Lexis on Atari Lynx is a smart and addictive puzzle game. Test your vocabulary under pressure in this original handheld title featuring multiple gameplay modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('loopz-usa-proto', 'Atari Lynx', 'Loopz (USA) (Proto)', '1993', 'Puzzle', 'Atari', '1', 'Pattern-matching puzzle', 'Puzzle-action game featuring pipe-linking mechanics.', 'Connect pieces of a loop to clear them before the timer runs out.', 'A rare unreleased prototype of the addictive link-building puzzle game.', 'Loopz (Proto) for Atari Lynx offers a look at a lost puzzle gem. Experience the fast-paced pattern matching and strategic planning of this challenging 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lynx-casino-usa-europe', 'Atari Lynx', 'Lynx Casino (USA, Europe)', '1991', 'Casino', 'Atari', '1', 'Gambling simulation collection', 'A collection of various casino-style gambling games.', 'Bet your virtual currency and try to strike it rich in the casino.', 'Features Blackjack, Craps, Poker, and more with detailed graphics.', 'Lynx Casino brings the Vegas experience to your handheld. Test your luck across multiple gambling classics in this polished and visually sharp simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lynx-ii-production-test-program-v002-usa-proto', 'Atari Lynx', 'Lynx II Production Test Program V0.02 (USA) (Proto)', '1991', 'Utility', 'Atari', '1', 'Hardware test program', 'Technical hardware diagnostic and production software.', 'Run internal tests to verify the Lynx II hardware functionality.', 'A fascinating piece of history used by Atari for quality control.', 'The Lynx II Production Test Program is a rare technical artifact. It provides a unique look at how Atari calibrated the system''s screen, sound, and controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('malibu-bikini-volleyball-usa-europe', 'Atari Lynx', 'Malibu Bikini Volleyball (USA, Europe)', '1992', 'Sports', 'Telegames', '1-2', 'Volleyball arcade sports', 'Two-on-two side-view beach volleyball simulation.', 'Win the tournament on the beaches of Malibu to become the champion.', 'A colorful sports game featuring large sprites and arcade gameplay.', 'Malibu Bikini Volleyball for Atari Lynx offers high-energy sun-soaked fun. Master the spikes and serves in this competitive and visually impressive sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marlboro-go!-europe-proto', 'Atari Lynx', 'Marlboro Go! (Europe) (Proto)', '1993', 'Advertising', 'Unknown', '1', 'Promotional arcade compilation', 'Top-down motorcycle racing prototype.', 'Race through various tracks in a branded promotional experience.', 'An unreleased advertising prototype created for the Marlboro brand.', 'Marlboro Go! (Proto) is a rare collector''s item for the Lynx. Experience the fast-paced bike racing mechanics of this unusual branded developmental build.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-usa-europe', 'Atari Lynx', 'Ms. Pac-Man (USA, Europe)', '1990', 'Action', 'Atari', '1-2', 'Classic arcade maze action', 'Fixed-screen maze game with scrolling elements.', 'Eat all the dots while avoiding ghosts across multiple maze layouts.', 'An excellent handheld version of the classic arcade sequel.', 'Ms. Pac-Man on Atari Lynx delivers authentic maze-chasing action. Featuring all the classic mazes and fruit bonuses, it''s a perfect fit for the portable screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-football-usa-europe', 'Atari Lynx', 'NFL Football (USA, Europe)', '1991', 'Sports', 'Atari', '1-2', 'American football arcade', 'Overhead American football sports simulation.', 'Lead your team through a full season to win the Super Bowl.', 'A detailed football sim with strategic play-calling and smooth action.', 'NFL Football for Atari Lynx brings the gridiron to your pocket. Execute complex plays and manage your team in this deep and competitive 8-bit sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden-usa-europe', 'Atari Lynx', 'Ninja Gaiden (USA, Europe)', '1991', 'Action', 'Tecmo', '1', 'Cinematic ninja action', 'Side-scrolling action-platformer and martial arts brawler.', 'Battle through levels to defeat the Jaquio and avenge your father.', 'A faithful port of the arcade hit with large, detailed sprites.', 'Ninja Gaiden on Atari Lynx is a technical powerhouse. Master the art of the ninja and survive brutal combat in this high-fidelity portable action classic.');
