INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-land-usa-europe', 'Atari Lynx', 'Pac-Land (USA, Europe)', '1991', 'Platformer', 'Namco', '1', 'Arcade platformer', 'Side-scrolling platformer based on the arcade spin-off.', 'Navigate Mickey through various worlds to find his way home.', 'A colorful and charming platformer with a unique "town-hopping" feel.', 'Pac-Land on Atari Lynx brings the whimsical world of the arcade to life. Master the jumps and discover hidden secrets in this vibrant 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-usa-europe', 'Atari Lynx', 'Paperboy (USA, Europe)', '1991', 'Action', 'Tengen', '1-2', 'Newspaper delivery arcade action', 'Isometric action-delivery game with arcade physics.', 'Deliver newspapers to your customers while avoiding neighborhood hazards.', 'A perfect port of the arcade classic featuring smooth scrolling.', 'Paperboy for Atari Lynx is a handheld delight. Dodge cars, dogs, and lawnmowers to keep your subscribers happy in this addictive neighborhood sim.');
