INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xenophobe-usa-europe', 'Atari Lynx', 'Xenophobe (USA, Europe)', '1992', 'Action', 'Atari Games', '1-2', 'Co-op sci-fi shooter', 'Side-scrolling multi-screen action-shooter.', 'Infiltrate alien bases and clear them of hostile lifeforms.', 'A faithful port of the unique arcade hit featuring large sprites.', 'Xenophobe on Atari Lynx brings the "split-screen" feel to a handheld. Battle diverse alien species and collect loot in this high-quality 8-bit arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xybots-usa-europe', 'Atari Lynx', 'Xybots (USA, Europe)', '1991', 'Shooter', 'Atari Games', '1-2', 'Isometric sci-fi shooter', 'Isometric 3D scrolling action-shooter.', 'Navigate through futuristic corridors to destroy robotic sentries.', 'A technically impressive port featuring smooth scrolling and co-op.', 'Xybots for Atari Lynx delivers intense maze-based combat. Master the 3D perspective and upgrade your weapons in this definitive 8-bit portable rendition of the hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zarlor-mercenary-usa-europe', 'Atari Lynx', 'Zarlor Mercenary (USA, Europe)', '1993', 'Shooter', 'Epyx', '1', 'Top-down sci-fi shooter', 'Side-scrolling horizontal shoot ''em up with a shop system.', 'Pilot a mercenary ship to destroy the alien Zarlor empire for profit.', 'A high-octane shooter featuring incredible boss battles and upgrades.', 'Zarlor Mercenary on Atari Lynx is a premier shmup for the system. Choose your pilot and blast through waves of enemies in this visually stunning and fast-paced 8-bit shooter.');